-- VISTA database schema (PostgreSQL). Generated by scripts/export_schema.py – do not edit by hand.
-- Apply with:  psql "$DATABASE_URL" -f database/schema.sql   (or run: cd backend && python -m app.seed)

CREATE TABLE hostels (
	id SERIAL NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	gender VARCHAR(10) NOT NULL, 
	description VARCHAR(300) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

CREATE TABLE login_attempts (
	id SERIAL NOT NULL, 
	email VARCHAR(120) NOT NULL, 
	success BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);
CREATE INDEX ix_login_attempts_created_at ON login_attempts (created_at);
CREATE INDEX ix_login_attempts_email ON login_attempts (email);

CREATE TABLE map_locations (
	id SERIAL NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	kind VARCHAR(20) NOT NULL, 
	x FLOAT NOT NULL, 
	y FLOAT NOT NULL, 
	description VARCHAR(200) NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE revoked_tokens (
	jti VARCHAR(64) NOT NULL, 
	revoked_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (jti)
);

CREATE TABLE blocks (
	id SERIAL NOT NULL, 
	hostel_id INTEGER NOT NULL, 
	name VARCHAR(40) NOT NULL, 
	floors INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (hostel_id, name), 
	FOREIGN KEY(hostel_id) REFERENCES hostels (id) ON DELETE CASCADE
);

CREATE TABLE rooms (
	id SERIAL NOT NULL, 
	block_id INTEGER NOT NULL, 
	number VARCHAR(10) NOT NULL, 
	floor INTEGER NOT NULL, 
	capacity INTEGER NOT NULL, 
	room_type VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (block_id, number), 
	FOREIGN KEY(block_id) REFERENCES blocks (id) ON DELETE CASCADE
);

CREATE TABLE users (
	id SERIAL NOT NULL, 
	email VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(120) NOT NULL, 
	full_name VARCHAR(100) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	phone VARCHAR(15) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	reg_no VARCHAR(20), 
	programme VARCHAR(60) NOT NULL, 
	year_of_study INTEGER, 
	gender VARCHAR(10) NOT NULL, 
	room_id INTEGER, 
	pref_sleep VARCHAR(20) NOT NULL, 
	pref_study VARCHAR(20) NOT NULL, 
	pref_food VARCHAR(20) NOT NULL, 
	looking_for_roommate BOOLEAN NOT NULL, 
	staff_type VARCHAR(20), 
	hostel_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (reg_no), 
	FOREIGN KEY(room_id) REFERENCES rooms (id) ON DELETE SET NULL, 
	FOREIGN KEY(hostel_id) REFERENCES hostels (id) ON DELETE SET NULL
);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_users_role ON users (role);

CREATE TABLE audit_logs (
	id SERIAL NOT NULL, 
	user_id INTEGER, 
	action VARCHAR(60) NOT NULL, 
	entity VARCHAR(40) NOT NULL, 
	entity_id VARCHAR(40) NOT NULL, 
	detail VARCHAR(500) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE INDEX ix_audit_logs_action ON audit_logs (action);
CREATE INDEX ix_audit_logs_created_at ON audit_logs (created_at);
CREATE INDEX ix_audit_logs_user_id ON audit_logs (user_id);

CREATE TABLE complaints (
	id SERIAL NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	student_id INTEGER NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	priority VARCHAR(10) NOT NULL, 
	title VARCHAR(120) NOT NULL, 
	description TEXT NOT NULL, 
	location VARCHAR(120) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	assigned_staff_id INTEGER, 
	escalated_to_id INTEGER, 
	escalated_at TIMESTAMP WITH TIME ZONE, 
	resolved_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(student_id) REFERENCES users (id), 
	FOREIGN KEY(assigned_staff_id) REFERENCES users (id), 
	FOREIGN KEY(escalated_to_id) REFERENCES users (id)
);
CREATE INDEX ix_complaints_created_at ON complaints (created_at);
CREATE INDEX ix_complaints_status ON complaints (status);
CREATE INDEX ix_complaints_student_id ON complaints (student_id);

CREATE TABLE delivery_requests (
	id SERIAL NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	sender_id INTEGER NOT NULL, 
	receiver_id INTEGER NOT NULL, 
	carrier_id INTEGER, 
	item_description VARCHAR(200) NOT NULL, 
	item_type VARCHAR(20) NOT NULL, 
	pickup_hostel_id INTEGER NOT NULL, 
	drop_hostel_id INTEGER NOT NULL, 
	pickup_point VARCHAR(120) NOT NULL, 
	fee INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	qr_token VARCHAR(64) NOT NULL, 
	failure_reason VARCHAR(300) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	accepted_at TIMESTAMP WITH TIME ZONE, 
	picked_up_at TIMESTAMP WITH TIME ZONE, 
	delivered_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(sender_id) REFERENCES users (id), 
	FOREIGN KEY(receiver_id) REFERENCES users (id), 
	FOREIGN KEY(carrier_id) REFERENCES users (id), 
	FOREIGN KEY(pickup_hostel_id) REFERENCES hostels (id), 
	FOREIGN KEY(drop_hostel_id) REFERENCES hostels (id)
);
CREATE INDEX ix_delivery_requests_carrier_id ON delivery_requests (carrier_id);
CREATE INDEX ix_delivery_requests_receiver_id ON delivery_requests (receiver_id);
CREATE INDEX ix_delivery_requests_sender_id ON delivery_requests (sender_id);
CREATE INDEX ix_delivery_requests_status ON delivery_requests (status);

CREATE TABLE gate_deliveries (
	id SERIAL NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	student_id INTEGER NOT NULL, 
	kind VARCHAR(10) NOT NULL, 
	vendor VARCHAR(80) NOT NULL, 
	courier_name VARCHAR(80) NOT NULL, 
	courier_phone VARCHAR(15) NOT NULL, 
	order_ref VARCHAR(40) NOT NULL, 
	expected_date VARCHAR(10) NOT NULL, 
	expected_time VARCHAR(5) NOT NULL, 
	gate VARCHAR(40) NOT NULL, 
	otp_hash VARCHAR(128) NOT NULL, 
	otp_plain_for_student VARCHAR(6) NOT NULL, 
	otp_attempts INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	handled_by_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	collected_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(student_id) REFERENCES users (id), 
	FOREIGN KEY(handled_by_id) REFERENCES users (id)
);
CREATE INDEX ix_gate_deliveries_student_id ON gate_deliveries (student_id);

CREATE TABLE lost_found_items (
	id SERIAL NOT NULL, 
	kind VARCHAR(10) NOT NULL, 
	title VARCHAR(120) NOT NULL, 
	description VARCHAR(500) NOT NULL, 
	location VARCHAR(120) NOT NULL, 
	item_date VARCHAR(10) NOT NULL, 
	contact VARCHAR(60) NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	reporter_id INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(reporter_id) REFERENCES users (id)
);

CREATE TABLE marketplace_items (
	id SERIAL NOT NULL, 
	seller_id INTEGER NOT NULL, 
	title VARCHAR(120) NOT NULL, 
	description VARCHAR(500) NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	condition VARCHAR(20) NOT NULL, 
	price INTEGER NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(seller_id) REFERENCES users (id)
);

CREATE TABLE mess_feedback (
	id SERIAL NOT NULL, 
	student_id INTEGER NOT NULL, 
	meal VARCHAR(20) NOT NULL, 
	food_rating INTEGER NOT NULL, 
	service_rating INTEGER NOT NULL, 
	comments VARCHAR(500) NOT NULL, 
	feedback_date VARCHAR(10) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id)
);

CREATE TABLE messages (
	id SERIAL NOT NULL, 
	sender_id INTEGER NOT NULL, 
	recipient_id INTEGER NOT NULL, 
	body VARCHAR(1000) NOT NULL, 
	is_read BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(sender_id) REFERENCES users (id), 
	FOREIGN KEY(recipient_id) REFERENCES users (id)
);
CREATE INDEX ix_messages_recipient_id ON messages (recipient_id);
CREATE INDEX ix_messages_sender_id ON messages (sender_id);

CREATE TABLE notices (
	id SERIAL NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	body TEXT NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	hostel_id INTEGER, 
	author_id INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(hostel_id) REFERENCES hostels (id), 
	FOREIGN KEY(author_id) REFERENCES users (id)
);
CREATE INDEX ix_notices_created_at ON notices (created_at);

CREATE TABLE notifications (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	body VARCHAR(500) NOT NULL, 
	link VARCHAR(120) NOT NULL, 
	kind VARCHAR(20) NOT NULL, 
	is_read BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX ix_notifications_created_at ON notifications (created_at);
CREATE INDEX ix_notifications_user_id ON notifications (user_id);

CREATE TABLE service_requests (
	id SERIAL NOT NULL, 
	kind VARCHAR(20) NOT NULL, 
	student_id INTEGER NOT NULL, 
	preferred_date VARCHAR(10) NOT NULL, 
	preferred_slot VARCHAR(20) NOT NULL, 
	meal_type VARCHAR(20) NOT NULL, 
	diet_notes VARCHAR(300) NOT NULL, 
	notes VARCHAR(300) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	assigned_staff_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id), 
	FOREIGN KEY(assigned_staff_id) REFERENCES users (id)
);
CREATE INDEX ix_service_requests_kind ON service_requests (kind);
CREATE INDEX ix_service_requests_status ON service_requests (status);
CREATE INDEX ix_service_requests_student_id ON service_requests (student_id);

CREATE TABLE sos_alerts (
	id SERIAL NOT NULL, 
	student_id INTEGER NOT NULL, 
	message VARCHAR(300) NOT NULL, 
	location VARCHAR(150) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	notified_at TIMESTAMP WITH TIME ZONE, 
	acknowledged_by_id INTEGER, 
	acknowledged_at TIMESTAMP WITH TIME ZONE, 
	resolved_by_id INTEGER, 
	resolved_at TIMESTAMP WITH TIME ZONE, 
	resolution_note VARCHAR(300) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id), 
	FOREIGN KEY(acknowledged_by_id) REFERENCES users (id), 
	FOREIGN KEY(resolved_by_id) REFERENCES users (id)
);
CREATE INDEX ix_sos_alerts_status ON sos_alerts (status);
CREATE INDEX ix_sos_alerts_student_id ON sos_alerts (student_id);

CREATE TABLE stored_files (
	id SERIAL NOT NULL, 
	owner_id INTEGER NOT NULL, 
	original_name VARCHAR(200) NOT NULL, 
	stored_name VARCHAR(80) NOT NULL, 
	content_type VARCHAR(80) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	purpose VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(owner_id) REFERENCES users (id), 
	UNIQUE (stored_name)
);

CREATE TABLE visitor_requests (
	id SERIAL NOT NULL, 
	student_id INTEGER NOT NULL, 
	visitor_name VARCHAR(100) NOT NULL, 
	relation VARCHAR(40) NOT NULL, 
	visitor_phone VARCHAR(15) NOT NULL, 
	visit_date VARCHAR(10) NOT NULL, 
	time_from VARCHAR(5) NOT NULL, 
	time_to VARCHAR(5) NOT NULL, 
	purpose VARCHAR(300) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	decided_by_id INTEGER, 
	decision_remark VARCHAR(300) NOT NULL, 
	decided_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id), 
	FOREIGN KEY(decided_by_id) REFERENCES users (id)
);
CREATE INDEX ix_visitor_requests_status ON visitor_requests (status);
CREATE INDEX ix_visitor_requests_student_id ON visitor_requests (student_id);

CREATE TABLE complaint_updates (
	id SERIAL NOT NULL, 
	complaint_id INTEGER NOT NULL, 
	actor_id INTEGER, 
	from_status VARCHAR(20), 
	to_status VARCHAR(20) NOT NULL, 
	note VARCHAR(500) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (id) ON DELETE CASCADE, 
	FOREIGN KEY(actor_id) REFERENCES users (id)
);
CREATE INDEX ix_complaint_updates_complaint_id ON complaint_updates (complaint_id);

CREATE TABLE handover_verifications (
	id SERIAL NOT NULL, 
	delivery_id INTEGER NOT NULL, 
	method VARCHAR(10) NOT NULL, 
	otp_hash VARCHAR(128) NOT NULL, 
	otp_plain_for_receiver VARCHAR(6) NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE, 
	attempts INTEGER NOT NULL, 
	max_attempts INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	receiver_name VARCHAR(100) NOT NULL, 
	receiver_reg_no VARCHAR(20) NOT NULL, 
	receiver_room VARCHAR(10) NOT NULL, 
	receiver_block VARCHAR(40) NOT NULL, 
	photo_file_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	verified_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(delivery_id) REFERENCES delivery_requests (id) ON DELETE CASCADE, 
	FOREIGN KEY(photo_file_id) REFERENCES stored_files (id)
);
CREATE INDEX ix_handover_verifications_delivery_id ON handover_verifications (delivery_id);

CREATE TABLE payments (
	id SERIAL NOT NULL, 
	delivery_id INTEGER NOT NULL, 
	amount INTEGER NOT NULL, 
	method VARCHAR(20) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	receipt_no VARCHAR(30) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (delivery_id), 
	FOREIGN KEY(delivery_id) REFERENCES delivery_requests (id) ON DELETE CASCADE, 
	UNIQUE (receipt_no)
);

CREATE TABLE shared_notes (
	id SERIAL NOT NULL, 
	author_id INTEGER NOT NULL, 
	title VARCHAR(120) NOT NULL, 
	subject VARCHAR(60) NOT NULL, 
	content TEXT NOT NULL, 
	file_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(author_id) REFERENCES users (id), 
	FOREIGN KEY(file_id) REFERENCES stored_files (id)
);

CREATE TABLE vault_documents (
	id SERIAL NOT NULL, 
	student_id INTEGER NOT NULL, 
	title VARCHAR(120) NOT NULL, 
	doc_type VARCHAR(30) NOT NULL, 
	file_id INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id), 
	FOREIGN KEY(file_id) REFERENCES stored_files (id)
);
CREATE INDEX ix_vault_documents_student_id ON vault_documents (student_id);
